import type {InstallPackageResponse} from '@remotion/studio-shared';
import {getRemotionEnvironment} from 'remotion';
import {callApi} from '../components/call-api';

export const installPackages = (
	packageNames: string[],
): Promise<InstallPackageResponse> => {
	if (!getRemotionEnvironment().isStudio) {
		throw new Error('installPackages() is only available in the Studio');
	}

	if (window.remotion_isReadOnlyStudio) {
		throw new Error('installPackages() is not available in Read-Only Studio');
	}

	return callApi('/api/install-package', {packageNames});
};

import fs from 'node:fs';
import path from 'node:path';

export const getInstalledDependencies = (remotionRoot: string) => {
	const packageJsonFilePath = path.join(remotionRoot, 'package.json');
	const packageJson = JSON.parse(fs.readFileSync(packageJsonFilePath, 'utf-8'));
	const dependencies = Object.keys(packageJson.dependencies ?? {});
	const devDependencies = Object.keys(packageJson.devDependencies ?? {});
	const optionalDependencies = Object.keys(
		packageJson.optionalDependencies ?? {},
	);
	const peerDependencies = Object.keys(packageJson.peerDependencies ?? {});

	return {
		dependencies,
		devDependencies,
		optionalDependencies,
		peerDependencies,
	};
};

