const LightAndDark: React.FC<{
	readonly text: string;
}> = ({text}) => {
	return (
		<CodeBlock
			className="shiki github-dark"
			language="bash"
			style={{
				backgroundColor: 'rgb(13, 17, 23)',
				color: 'rgb(201, 209, 217)',
			}}
		>
			<div className="code-container">
				<div className="line">{text}</div>
			</div>
		</CodeBlock>
	);
};

export const Installation: React.FC<{
	readonly pkg: string;
}> = ({pkg}) => {
	if (pkg === undefined) {
		throw new Error('pkg is undefined');
	}

	const packages = pkg
		.split(' ')
		.map((p) => {
			if (p.startsWith('@remotion') || p === 'remotion') {
				return `${p}@${VERSION}`;
			}

			return p;
		})
		.join(' ');

	const isRemotionPackage = packages.includes('remotion');

	return (
		<div>
			<Tabs
				defaultValue="npm"
				values={[
					{label: 'npm', value: 'npm'},
					{label: 'bun', value: 'bun'},
					{label: 'pnpm', value: 'pnpm'},
					{label: 'yarn', value: 'yarn'},
				]}
			>
				<TabItem value="npm">
					<LightAndDark text={`npm i --save-exact ${packages}`} />
				</TabItem>
				<TabItem value="pnpm">
					<LightAndDark text={`pnpm i ${packages}`} />
				</TabItem>
				<TabItem value="bun">
					<LightAndDark text={`bun i ${packages}`} />
				</TabItem>
				<TabItem value="yarn">
					<LightAndDark text={`yarn --exact add ${packages}`} />
				</TabItem>
			</Tabs>
			{isRemotionPackage ? (
				<>
					This assumes you are currently using v{VERSION} of Remotion.
					<br />
					Also update <code>remotion</code> and all <code>`@remotion/*`</code>{' '}
					packages to the same version.
					<br />
					Remove all <code>^</code> character in front of the version numbers of
					it as it can lead to a version conflict.
				</>
			) : null}
		</div>
	);
};

import {GoogleAuth} from 'google-auth-library';
import {
	getProjectId,
	isInCloudTask,
} from '../../functions/helpers/is-in-cloud-task';

export const getAuthClientForUrl = async (url: string) => {
	let auth = new GoogleAuth();
	if (isInCloudTask()) {
		auth = new GoogleAuth({
			projectId: getProjectId(),
		});
	} else {
		auth = new GoogleAuth({
			projectId: process.env.REMOTION_GCP_PROJECT_ID,
			credentials: {
				client_email: process.env.REMOTION_GCP_CLIENT_EMAIL,
				private_key: process.env.REMOTION_GCP_PRIVATE_KEY,
			},
		});
	}

	const client = await auth.getIdTokenClient(url);
	return client;
};

